    internal static bool TryGetAttributeType(string key, out RegistryAttributeValueKind kind)
    {
        if (AttributeKinds.TryGetValue(key, out kind)) return true;
        foreach (var template in TemplateKinds)
        {
            if (key.Length > template.Prefix.Length && key.StartsWith(template.Prefix, StringComparison.Ordinal))
            {
                kind = template.Kind;
                return true;
            }
        }

        kind = RegistryAttributeValueKind.Unknown;
        return false;
    }

    internal static bool TryGetCanonicalEnumValue(string key, string value, out string? canonical)
    {
        canonical = null;
        if (!EnumValues.TryGetValue(key, out var values))
            return false;

        foreach (var candidate in values)
        {
            if (string.Equals(candidate, value, StringComparison.OrdinalIgnoreCase))
            {
                canonical = candidate;
                return true;
            }
        }

        return false;
    }

    internal static bool IsGenAiSpanDiscriminator(string key) => GenAiSpanDiscriminatorKeys.Contains(key);

    internal static bool IsKnownAttributeKey(string key) => TryGetAttributeType(key, out _);

    /// <summary>
    /// True only for a key the registry defines outright; a key that merely extends a
    /// template such as <c>http.request.header.</c> is not one.
    /// </summary>
    internal static bool IsRegistryAttributeKey(string key) =>
        AttributeKinds.ContainsKey(key);

    internal static bool IsKnownMetricName(string name) => KnownMetricNames.Contains(name);

    internal static bool IsKnownScopeName(string name) => KnownScopeNames.Contains(name);

    internal static bool IsKnownEventName(string name) => KnownEventNames.Contains(name);

    internal static bool TryResolveSpanRule(
        IReadOnlyDictionary<string, string> attributes,
        string spanKind,
        out SemconvSpanRule? rule)
    {
        foreach (var candidate in SpanRules)
        {
            if (!string.Equals(candidate.Kind, spanKind, StringComparison.OrdinalIgnoreCase)
                || !attributes.TryGetValue(candidate.DiscriminatorKey, out var discriminatorValue)
                || !candidate.DiscriminatorValues.Contains(discriminatorValue, StringComparer.Ordinal))
            {
                continue;
            }

            if (candidate.ConstraintKey is not null
                && (!attributes.TryGetValue(candidate.ConstraintKey, out var constraintValue)
                    || !string.Equals(constraintValue, candidate.ConstraintValue, StringComparison.Ordinal)))
            {
                continue;
            }

            rule = candidate;
            return true;
        }

        rule = null;
        return false;
    }
}
